void test_gimp_image_save_load_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar *temp_file;
  GimpImage *loaded_image;
  gint fd;

  image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file = g_strdup_printf("/tmp/gimp_test_image_%d.xcf", getpid());
  fd = g_creat(temp_file, S_IRUSR | S_IWUSR);
