  g_free(temp_file);
  g_object_unref(image);
}

void test_gimp_image_save_load(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar *temp_file;
  GimpImage *loaded_image;
  GError *error = NULL;

  image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_return_if_fail(image != NULL);

  temp_file = g_strdup_printf("/tmp/gimp_test_image_%d.xcf", (int) gimp_get_new_temp_file_id());

  if (!gimp_file_save(GIMP_FILE_SAVE_EXPORT, GIMP_FILE_SAVE_OVERWRITE, GIMP_FILE_SAVE_NORMAL, NULL, NULL, NULL, image, temp_file, "XCF", &error)) {
    g_printerr("Failed to save the image: %s\n", error->message);
    g_error_free(error);
    g_object_unref(image);
    g_free(temp_file);
    return;
  }

  loaded_image = gimp_file_load(GIMP_FILE_LOAD_NORMAL, temp_file, NULL, &error);
  if (loaded_image == NULL) {
    g_printerr("Failed to load the image: %s\n", error->message);
    g_error_free(error);
    g_object_unref(image);
    g_unlink(temp_file);
    g_free(temp_file);
    return;
  }

  g_return_if_fail(loaded_image != NULL);
  g_return_if_fail(gimp_image_width(loaded_image) == gimp_image_width(image));
  g_return_if_fail(gimp_image_height(loaded_image) == gimp_image_height(image));

  g_object_unref(loaded_image);
  g_unlink(temp_file);
  g_free(temp_file);
  g_object_unref(image);
}

void test_gimp_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image = create_test_gimp_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  gchar *temp_file = g_strdup_printf("/tmp/gimp-test-image-%d.xcf", getpid());
  gimp_image_save(image, temp_file, NULL);

  GimpImage *loaded_image = gimp_image_load(temp_file, NULL);
  g_assert(loaded_image != NULL);

  g_assert(compare_images(image, loaded_image));

  g_object_unref(image);
  g_object_unref(loaded_image);
  g_unlink(temp_file);
  g_free(temp_file);
}

void test_gimp_image_save_load_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar *temp_file;
  GimpImage *loaded_image;
  GError *error = NULL;
  gint fd;

  image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_return_if_fail(image != NULL);

  temp_file = g_strdup_temp("/tmp/gimp-test-XXXXXX", NULL);
  fd = g_creat(temp_file, S_IRWXU);
  g_return_if_fail(fd != -1);

  g_object_unref(image);

  if (!gimp_file_save(GIMP_FILE_SAVE_DIALOG(NULL), temp_file, NULL, &error)) {
    g_critical("Failed to save image: %s", error->message);
    g_error_free(error);
    close(fd);
    g_unlink(temp_file);
    g_free(temp_file);
    return;
  }

  close(fd);

  loaded_image = gimp_file_load(temp_file, NULL, &error);
  g_return_if_fail(loaded_image != NULL);

  g_object_unref(loaded_image);

  g_unlink(temp_file);
  g_free(temp_file);
}

void test_gimp_image_save_load_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar     *temp_path;
  GimpImage *loaded_image;
  gint       fd;
  gboolean   success;

  image = create_test_gimp_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_path = g_strdup_temp("gimp-test-XXXXXX.xcf");
  fd = g_mkstemp(temp_path);
  g_assert(fd >= 0);

  success = gimp_xcf_save_image(temp_path, image);
  g_assert(success);

  loaded_image = gimp_xcf_load_image(temp_path);
  g_assert(loaded_image != NULL);

  g_assert(compare_gimp_images(image, loaded_image));

  g_remove(temp_path);
  g_free(temp_path);

  gimp_image_delete(image);
  gimp_image_delete(loaded_image);
}
